    "självrättning": true,
    "svarFormat": "numeriskt",
    "svarEnhet": "N",
    "familjNyckelTidigare": "vagrorelser__vagfart_frekvens_och_vaglangd",
    "familjTidigare": "Vågrörelser: fart, reflektion och brytning",
